import{at as e,it as t,n,vt as r}from"./chunks/framework.D9OOHiq-.js";var i=JSON.parse(`{"title":"审计与签名","description":"","frontmatter":{},"headers":[],"relativePath":"modules/forge/audit.md","filePath":"modules/forge/audit.md","lastUpdated":0}`),a={name:`modules/forge/audit.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="审计与签名" tabindex="-1">审计与签名 <a class="header-anchor" href="#审计与签名" aria-label="Permalink to “审计与签名”">​</a></h1><p>锻造成功后会往成品物品里写入哪些追溯数据, 它们存在哪里, 以及它们和物品刷新之间的关系</p><p>锻造成功后, Forge 会往结果物品里写入审计数据, 用来追溯锻造来源, 并验证物品有没有被篡改</p><h2 id="数据落在哪里" tabindex="-1">数据落在哪里 <a class="header-anchor" href="#数据落在哪里" aria-label="Permalink to “数据落在哪里”">​</a></h2><p>锻造审计数据同时存在于两个地方:</p><ol><li><strong>CoreLib 物品层快照</strong>: namespace 为 <code>forge</code>, layer version 为 <code>1</code>, payload 就是下面的审计字段表. 刷新物品时从这里读回</li><li><strong><code>emakiforge:forge</code> PDC 分区</strong>: 把关键字段压成扁平的键, 供占位符和变量系统读取. 见<a href="#锻造层-pdc-键">锻造层 PDC 键</a></li></ol><h2 id="审计字段" tabindex="-1">审计字段 <a class="header-anchor" href="#审计字段" aria-label="Permalink to “审计字段”">​</a></h2><p>锻造完成后, 下面这些字段会写进审计 payload:</p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td><code>schema</code></td><td>审计结构的标识, 当前固定是 <code>forge_audit_v2</code></td></tr><tr><td><code>schema_version</code></td><td>审计结构版本, 当前为 <code>2</code></td></tr><tr><td><code>stage</code></td><td>来源阶段, 当前固定为 <code>forge</code></td></tr><tr><td><code>recipe_id</code></td><td>使用的配方 ID</td></tr><tr><td><code>quality</code></td><td>品质等级名称; 品质没解析出来时是空字符串</td></tr><tr><td><code>multiplier</code></td><td>品质倍率</td></tr><tr><td><code>forged_at</code></td><td>锻造时间戳 (毫秒)</td></tr><tr><td><code>materials_signature</code></td><td>材料贡献数据算出来的一段哈希签名</td></tr><tr><td><code>output_item</code></td><td>输出物品来源的简写. 只有配方配置了输出物品来源时才写入</td></tr><tr><td><code>materials</code></td><td>材料贡献列表, 见下表</td></tr></tbody></table><p><code>materials[]</code> 每个条目的字段:</p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td><code>material_id</code> / <code>count_key</code> / <code>audit_id</code></td><td>材料的身份键. 只有配置里显式声明过才写入; 没声明时这个键会被移除</td></tr><tr><td><code>material_item</code></td><td>兼容身份: 物品源简写, 或 <code>matcher:&lt;摘要&gt;</code></td></tr><tr><td><code>category</code></td><td>材料分类 (必需还是可选)</td></tr><tr><td><code>amount</code></td><td>计划投入的数量</td></tr><tr><td><code>amount_consumed</code></td><td>实际消耗的数量</td></tr><tr><td><code>slot</code></td><td>材料所在的界面槽位</td></tr><tr><td><code>sequence</code></td><td>处理顺序</td></tr><tr><td><code>matched_source</code></td><td>实际匹配到的物品源简写</td></tr><tr><td><code>matcher</code></td><td>matcher 的摘要键; 没有 matcher 时是空字符串</td></tr><tr><td><code>allocation</code></td><td>这一条材料在各个槽位上的分配明细</td></tr><tr><td><code>legacy_identity</code> / <code>identity_diagnostic</code></td><td>当有身份键没显式声明时, 补充的兼容身份和诊断标记</td></tr></tbody></table><h2 id="材料签名" tabindex="-1">材料签名 <a class="header-anchor" href="#材料签名" aria-label="Permalink to “材料签名”">​</a></h2><p><code>materials_signature</code> 只对实际消耗量大于 0 的材料贡献计算哈希签名. 算签名时用到的输入包括材料定义摘要, 数量, 消耗量, 槽位, 分类, 顺序, 匹配来源和分配明细. 相同的材料贡献组合总是得到相同的签名, 所以可以用它来比对物品的锻造材料数据和自己预期的是不是一致</p><h2 id="锻造层-pdc-键" tabindex="-1">锻造层 PDC 键 <a class="header-anchor" href="#锻造层-pdc-键" aria-label="Permalink to “锻造层 PDC 键”">​</a></h2><p>命名空间 <code>emakiforge</code>, 分区 <code>forge</code> 下的扁平键:</p><table tabindex="0"><thead><tr><th>键</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>forge_recipe_id</code></td><td>string</td><td>锻造出这个物品用的配方 ID</td></tr><tr><td><code>quality_id</code></td><td>string</td><td>品质 ID (与品质名同值)</td></tr><tr><td><code>quality_display</code></td><td>string</td><td>品质显示名</td></tr><tr><td><code>quality_multiplier</code></td><td>string</td><td>品质倍率, 按 <code>0.##</code> 格式化之后存进去</td></tr><tr><td><code>material_id</code></td><td>string</td><td>显式声明过的 <code>material_id</code> 列表, 用逗号连在一起; 没有就移除这个键</td></tr><tr><td><code>count_key</code></td><td>string</td><td>显式声明过的 <code>count_key</code> 列表, 用逗号连在一起; 没有就移除这个键</td></tr><tr><td><code>audit_id</code></td><td>string</td><td>显式声明过的 <code>audit_id</code> 列表, 用逗号连在一起; 没有就移除这个键</td></tr><tr><td><code>matched_source</code></td><td>string</td><td>匹配到的来源简写列表, 用逗号连在一起</td></tr><tr><td><code>amount_consumed</code></td><td>integer</td><td>全部材料实际消耗量加起来的总数</td></tr><tr><td><code>matcher_digest</code></td><td>string</td><td>matcher 摘要列表, 用逗号连在一起</td></tr><tr><td><code>allocation</code></td><td>string</td><td>分配明细算出来的一段签名</td></tr></tbody></table><p>这些键会被 CoreLib 变量系统读取为 <code>forge_quality_id</code>, <code>forge_quality_display</code>, <code>forge_quality_multiplier</code>, <code>forge_recipe_id</code> 四个变量</p><h2 id="与刷新的关系" tabindex="-1">与刷新的关系 <a class="header-anchor" href="#与刷新的关系" aria-label="Permalink to “与刷新的关系”">​</a></h2><p>Forge 的物品刷新服务会读审计数据里的 <code>recipe_id</code> 和 <code>quality</code>, 照着它们重建锻造层的展示. 审计数据缺失, 品质已经不在当前品质池里, 或者配方已经被删掉时, 这件物品就无法重建锻造层展示, 并且会打一条警告</p><p>读材料审计记录时, 现在的实现按 <code>audit_id</code> → <code>material_id</code> → <code>count_key</code> → 旧 <code>material_item</code> / <code>source</code> 的顺序逐个尝试. 用旧身份成功解析出来之后, 会标记成需要迁移, 并在刷新时重建; 身份全部解析不出来时, 保留原物品并记一条 warning, 不会用不完整的结果覆盖原来的状态.<strong>材料的身份键必须保持不变</strong>: 纯 matcher 材料会按 matcher 内容摘要推导身份, 改动 matcher 之后, 旧成品会报&quot;未找到材料&quot; (<code>console.forge_refresh_missing_material</code>). 这个行为已经由源码证实, 但本轮没有在真实的 Paper/Folia 服务器上验证旧 PDC 审计数据</p><h2 id="用途场景" tabindex="-1">用途场景 <a class="header-anchor" href="#用途场景" aria-label="Permalink to “用途场景”">​</a></h2><ul><li>交易或回收系统可以读审计数据, 判断物品的配方来源和品质</li><li>外部统计可以按 <code>recipe_id</code>, <code>quality</code> 和 <code>forged_at</code> 汇总锻造产出</li></ul><div class="note custom-block"><p class="custom-block-title custom-block-title-default">NOTE</p><p>Forge 没有提供查看审计数据的内置命令. 需要人工查看时, 请用能读物品 PDC 和物品层快照的外部工具</p></div>`,23)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};